using Microsoft.VisualStudio.TestTools.UnitTesting;
using WPFUI.Factories;
using WPFUI.Models;

namespace TestEngine.Models
{
    [TestClass]
    public class TestCombat
    {
        private static Player NewPlayer(int maximumHitPoints = 10) =>
            new Player("Test Player", "Fighter",
                experience: 0, maximumHitPoints: maximumHitPoints,
                currentHitPoints: maximumHitPoints,dexterity: 5, gold: 0);

        [TestMethod]
        public void AttackingAMonsterReducesItsHitPoints()
        {
            Player player = NewPlayer();
            player.AddItemToInventory(ItemFactory.CreateGameItem(1001)); // Pointy Stick, 1-2 damage
            player.CurrentWeapon = player.Inventory.Weapons[0];

            Monster snake = MonsterFactory.GetMonster(1);
            int startingHitPoints = snake.CurrentHitPoints;

            player.UseCurrentWeaponOn(snake);

            Assert.IsTrue(snake.CurrentHitPoints < startingHitPoints,
                $"expected damage, but hit points went from {startingHitPoints} to {snake.CurrentHitPoints}");
        }

        [TestMethod]
        public void EnoughAttacksKillsAMonster()
        {
            Player player = NewPlayer();
            player.AddItemToInventory(ItemFactory.CreateGameItem(1001));
            player.CurrentWeapon = player.Inventory.Weapons[0];

            Monster snake = MonsterFactory.GetMonster(1);
            bool killedEventRaised = false;
            snake.OnKilled += (sender, args) => killedEventRaised = true;

            // Pointy Stick does at least 1 damage per hit and the snake has 4 hit points,
            // so 20 swings is far more than enough even with misses.
            for (int i = 0; i < 20 && !snake.IsDead; i++)
            {
                player.UseCurrentWeaponOn(snake);
            }

            Assert.IsTrue(snake.IsDead, "snake survived 20 attacks");
            Assert.AreEqual(0, snake.CurrentHitPoints, "a dead entity should sit at exactly 0 hit points");
            Assert.IsTrue(killedEventRaised, "OnKilled was never raised");
        }

        [TestMethod]
        public void AConsumableHealsItsUser()
        {
            Player player = NewPlayer();
            player.TakeDamage(5);
            player.AddItemToInventory(ItemFactory.CreateGameItem(2001)); // Granola bar, heals 2
            player.CurrentConsumable = player.Inventory.Consumables[0];

            player.UseCurrentConsumable();

            Assert.AreEqual(7, player.CurrentHitPoints);
            Assert.IsFalse(player.Inventory.HasConsumable, "the consumable should be gone after use");
            Assert.IsNull(player.CurrentConsumable, "a consumed item should no longer be selected");
        }

        [TestMethod]
        public void TwoHoldersOfTheSameItemTypeDoNotShareActionMessages()
        {
            Monster first = MonsterFactory.GetMonster(1);
            Monster second = MonsterFactory.GetMonster(1);

            int messagesFromFirst = 0;
            first.OnActionPerformed += (sender, message) => messagesFromFirst++;

            second.UseCurrentWeaponOn(NewPlayer());

            Assert.AreEqual(0, messagesFromFirst,
                "an attack by one monster was reported by another holding a clone of the same weapon");
        }
    }
}

