using WPFUI.Models;
using WPFUI.Services;

namespace WPFUI.Actions;

public class AttackWithWeapon : BaseAction, IAction
{
    private readonly int _maximumDamage;
    private readonly int _minimumDamage;

    public AttackWithWeapon(GameItem itemInUse,int minimumDamage, int maximumDamage) : base(itemInUse)
    {
        if(itemInUse.Category != GameItem.ItemCategory.Weapon)
        {
            throw new ArgumentException($"{itemInUse.Name} is not a weapon");
        }
        if(maximumDamage < minimumDamage)
        {
            throw new ArgumentException($"maximum damage must be >= minimum damage");
        }
        if(minimumDamage < 0)
        {
            throw new ArgumentException($"minimum damage must be 0 or more");
        }
        _minimumDamage = minimumDamage;
        _maximumDamage = maximumDamage;
    }

    public IAction Clone(GameItem newItemInUse)
    {
        return new AttackWithWeapon(newItemInUse, _minimumDamage, _maximumDamage);
    }

    public void Execute(LivingEntity actor, LivingEntity target)
    {   
        if(CombatService.AttackSucceeded(actor, target)){
            int damage = RandomNumberGenerator.NumberBetween(_minimumDamage, _maximumDamage);
            ReportResult($"{actor.Name.ToUpper()} hit {target.Name.ToLower()} for {damage} point{(damage > 1 ? "s" : "")}");
            target.TakeDamage(damage);
        }
        else
        {
            ReportResult($"{actor.Name.ToUpper()} missed {target.Name.ToLower()}");
        }
    }
}

